import re

_PATTERN = re.compile(r"^(?:(\d+(?:\.\d+)?)h)?(?:(\d+(?:\.\d+)?)m)?(?:(\d+(?:\.\d+)?)s)?$")


def parse_duration(text):
    """Parse a duration like '1h30m', '1.5h', '45s' or '2h' into seconds."""
    if not isinstance(text, str):
        raise ValueError(f"invalid duration: {text!r}")
    match = _PATTERN.fullmatch(text.strip())
    if match is None:
        raise ValueError(f"invalid duration: {text!r}")
    def seconds(part):
        if part is None:
            return 0.0
        value = float(part)
        if value != int(value):
            return value
        return value
    hours, minutes, seconds_ = (seconds(p) for p in match.groups())
    total = hours * 3600 + minutes * 60 + seconds_
    result = round(total)
    if abs(total - result) > 1e-9 * max(1.0, abs(total)):
        raise ValueError(f"invalid duration (fractional seconds): {text!r}")
    return result

