    "h": 3600,
    "m": 60,
    "s": 1,
}

_TOKEN = re.compile(r"(\d+(?:\.\d+)?)\s*(d(?:ays?)?|h(?:ours?)?|m(?:inutes?)?|s(?:econds?)?)", re.IGNORECASE)


def _unit_key(unit):
    """Map any accepted unit spelling to its canonical letter."""
    return unit[0].lower()


def parse_duration(text):
    """Parse a duration like '1d1h30m', '1.5h', '45s', '2h' or '1 hour 30 minutes' into seconds."""
    if not isinstance(text, str):
        raise ValueError(f"invalid duration: {text!r}")
    body = text.strip()
    if not body:
        raise ValueError(f"invalid duration: {text!r}")

    total = 0.0
    pos = 0
    seen = set()
    last_order = 4  # orders: d=3, h=2, m=1, s=0; must strictly decrease
    while pos < len(body):
