            pos += 1
            continue
        match = _TOKEN.match(body, pos)
        if match is None:
            raise ValueError(f"invalid duration: {text!r}")
        value, unit = match.group(1), match.group(2)
        letter = _unit_key(unit)
        order = {"d": 3, "h": 2, "m": 1, "s": 0}[letter]
